<section class="hero"><h1>Raportet e emailit dhe aksioneve</h1><p>Të dërguara: <?=number_format((int)($summary['sent']??0))?> · Dështuara: <?=number_format((int)($summary['failed']??0))?> · Gjithsej: <?=number_format((int)($summary['total']??0))?></p></section>
<section class="panel"><div class="table-wrap"><table><thead><tr><th>Data</th><th>Lloji</th><th>Emaili</th><th>Subjekti</th><th>Statusi</th><th>Aksioni</th><th>Pranuar / shikuar</th><th>Klikime</th></tr></thead><tbody><?php foreach($messages as $m):?><tr><td><?=e($m['queued_at'])?></td><td><?=e($m['message_type'])?></td><td><?=e($m['recipient_email'])?></td><td><?=e($m['subject'])?></td><td><span class="badge"><?=e($m['status_code'])?></span><?php if($m['failure_message']):?><br><small><?=e($m['failure_message'])?></small><?php endif;?></td><td><?=e($m['action_code']??'—')?></td><td><?=e($m['first_opened_at']??'—')?></td><td><?=(int)($m['open_count']??0)?></td></tr><?php endforeach;?></tbody></table><?php if($messages===[]):?><div class="empty">Nuk ka emaila të regjistruar.</div><?php endif;?></div></section>
